package com.bank.backpressure.model;

// A partition log: records are produced (appended) and consumed by offset.
public class Partition {
    private final int id;
    private long logEndOffset = 0;   // next produce position
    private long committedOffset = 0; // consumer position

    public Partition(int id) { this.id = id; }

    public void produce(int count) { logEndOffset += count; }

    // Pull up to maxRecords; returns how many were fetched (bounded by availability).
    public long fetch(long maxRecords) {
        long available = logEndOffset - committedOffset;
        return Math.min(available, maxRecords);
    }

    public void commit(long processed) { committedOffset += processed; } // manual commit

    public long lag() { return logEndOffset - committedOffset; }
    public int getId() { return id; }
}
