package com.bank.backpressure.consumer;

import com.bank.backpressure.model.Partition;
import java.util.logging.*;

// Pulls a bounded batch, processes at its own pace, commits manually.
public class PullConsumer {
    private static final Logger log = Logger.getLogger(PullConsumer.class.getName());

    private final String id;
    private final long maxPollRecords;   // backpressure: bound intake per poll
    private final long processPerTick;   // how many it can actually process per tick

    public PullConsumer(String id, long maxPollRecords, long processPerTick) {
            this.id = id;
            this.maxPollRecords = maxPollRecords
            this.processPerTick = processPerTick;
    }

    // One poll cycle on one partition: fetch bounded, process at own speed, commit.
    public long pollOnce(Partition p) {
        long fetched = p.fetch(maxPollRecords);
        long processed = Math.min(fetched, processPerTick); // slow consumer processes less
        p.commit(processed);                                // commit AFTER processing
        log.fine(() -> id + " P" + p.getId() + " fetched=" + fetched
            + " processed=" + processed + " lag=" + p.lag());
        return processed;
    }
}
