package com.bank.backpressure.consumer;

import com.bank.backpressure.model.Partition;
import java.util.*;

// Distributes partitions across consumers (one partition per consumer at most).
public class ConsumerGroup {
    private final List<PullConsumer> consumers = new ArrayList<>();
    private final List<Partition> partitions;

    public ConsumerGroup(List<Partition> partitions) { this.partitions = partitions; }

    public void addConsumer(PullConsumer c) { consumers.add(c); }

    // Each consumer polls the partitions assigned to it (round-robin assignment).
    public long runTick() {
        long totalProcessed = 0;
        for (int pi = 0; pi < partitions.size(); pi++) {
            if (consumers.isEmpty()) break;
            PullConsumer owner = consumers.get(pi % consumers.size());
            totalProcessed += owner.pollOnce(partitions.get(pi));
        }
        return totalProcessed;
    }

    public long totalLag() { return partitions.stream().mapToLong(Partition::lag).sum(); }
    public int consumerCount() { return consumers.size(); }
}
