package com.bank.backpressure;

import com.bank.backpressure.consumer.ConsumerGroup;
import com.bank.backpressure.consumer.PullConsumer;
import com.bank.backpressure.model.Partition;
import java.util.*;
import java.util.logging.*;

public class BackpressureDemo {
    private static final Logger log = Logger.getLogger(BackpressureDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // 4 partitions, producing 400 records/tick at peak.
        List<Partition> partitions = new ArrayList<>();
        for (int i = 0; i < 4; i++) partitions.add(new Partition(i));

        // Phase 1: ONE slow consumer (processes 50/tick). Lag grows (backpressure -> lag).
        ConsumerGroup group = new ConsumerGroup(partitions);
        group.addConsumer(new PullConsumer("c1", 100, 50));
        log.info("Phase 1: 1 slow consumer");
        for (int tick = 1; tick <= 3; tick++) {
            partitions.forEach(p -> p.produce(100)); // 400/tick produced
            group.runTick();
            log.warning("  tick " + tick + " totalLag=" + group.totalLag()
                + " (pull model: unprocessed stays in log as durable lag)");
        }

        // Phase 2: scale to 4 consumers (= partition count). Throughput rises, lag drains.
        group.addConsumer(new PullConsumer("c2", 100, 100));
        group.addConsumer(new PullConsumer("c3", 100, 100));
        group.addConsumer(new PullConsumer("c4", 100, 100));
        log.info("Phase 2: scaled to " + group.consumerCount() + " consumers (= 4 partitions)");
        for (int tick = 4; tick <= 7; tick++) {
            partitions.forEach(p -> p.produce(100));
            group.runTick();
            log.info("  tick " + tick + " totalLag=" + group.totalLag() + " (draining)");
        }
        log.info("Scaling consumers UP TO partition count raised throughput and drained lag.");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
